16	import type { Core } from '@strapi/strapi';
17	
18	// ---------------------------------------------------------------------------
19	// Types
20	// ---------------------------------------------------------------------------
21	
22	interface ValidationRule {
23	  rule:
24	    | 'required'
25	    | 'min'
26	    | 'max'
27	    | 'minLength'
28	    | 'maxLength'
29	    | 'pattern'
30	    | 'email'
31	    | 'rutCL'
32	    | 'cedulaCO'
33	    | 'plateCO'
34	    | 'plateCL'
35	    | 'vehicleYear'
36	    | 'minAge';
37	  params?: Record<string, unknown> | null;
38	  errorMessage?: string;
39	}
40	
41	interface FieldOption {
42	  value: string;
43	  label: string;
44	  order: number;
45	}
46	
47	interface FormFieldSeed {
48	  key: string;
49	  label: string;
50	  type: 'text' | 'number' | 'select' | 'date' | 'checkbox';
51	  section: 'applicant' | 'vehicle';
52	  required: boolean;
53	  helpText?: string;
54	  errorMessage: string;
55	  order: number;
56	  defaultValue?: string;
57	  autocomplete?: string;
58	  options?: FieldOption[];
59	  validations?: ValidationRule[];
60	}
61	
