1	/**
2	 * ApplicantFormComponent — Step 1 of the wizard.
3	 * Dynamically renders form fields configured in Strapi (RN-01.1, RN-01.7).
4	 * Implements loading (AC-01.9), error (AC-01.10), empty (AC-01.11) states.
5	 * Persists to WizardStore on valid advance (AC-01.5).
6	 * Focuses first invalid field on submit attempt (AC-01.3).
7	 * AC-01.1, AC-01.2, AC-01.3, AC-01.4, AC-01.5, AC-01.8, AC-01.9, AC-01.10, AC-01.11, AC-01.12, AC-01.13, AC-01.14, AC-01.15
8	 */
9	import {
10	  ChangeDetectionStrategy,
11	  Component,
12	  OnDestroy,
13	  OnInit,
14	  computed,
15	  inject,
16	  signal,
17	  viewChildren,
18	} from '@angular/core';
19	import { ReactiveFormsModule, FormControl, FormGroup } from '@angular/forms';
20	import { Router } from '@angular/router';
21	import { Subscription } from 'rxjs';
22	
23	import type { FormField } from '../../core/schemas/form-field.schema';
24	import { StrapiClient } from '../../core/strapi.client';
25	import { SYSTEM_MESSAGES } from '../../core/system-messages';
26	import { CountryContext } from '../../country/country.context';
27	import { WizardStore } from '../../wizard/wizard.store';
28	import { buildValidators } from './validator-registry';
29	import { FieldRendererComponent } from './field-renderer.component';
30	
31	type LoadState = 'loading' | 'error' | 'empty' | 'ready';
32	
33	@Component({
34	  selector: 'app-applicant-form',
35	  standalone: true,
36	  changeDetection: ChangeDetectionStrategy.OnPush,
37	  imports: [ReactiveFormsModule, FieldRendererComponent],
38	  template: `
39	    <main class="form-page" aria-labelledby="form-title">
40	      <h1 id="form-title" class="form-title" tabindex="-1">
41	        {{ stepTitle() }}
42	      </h1>
43	
44	      @switch (loadState()) {
45	        @case ('loading') {
46	          <div role="status" class="state-loading" aria-live="polite">
47	            <span class="visually-hidden">{{ msgs['form.loading'] }}</span>
48	            <div class="loading-spinner" aria-hidden="true"></div>
49	            <p>{{ msgs['form.loading'] }}</p>
50	          </div>
51	        }
52	
53	        @case ('error') {
54	          <div role="alert" class="state-error">
55	            <p>{{ msgs['form.loadError'] }}</p>
56	            <button
57	              type="button"
58	              class="btn btn--secondary"
59	              (click)="loadFields()"
60	            >
61	              {{ msgs['form.retry'] }}
62	            </button>
63	          </div>
64	        }
65	
66	        @case ('empty') {
67	          <div role="status" class="state-empty">
68	            <p>{{ msgs['form.empty'] }}</p>
69	          </div>
70	        }
71	
72	        @case ('ready') {
73	          <form
74	            [formGroup]="form()"
75	            (ngSubmit)="onSubmit()"
76	            novalidate
77	            class="applicant-form"
78	          >
79	            @for (field of fields(); track field.documentId) {
80	              <app-field-renderer
81	                [field]="field"
82	                [formGroup]="form()"
83	              />
84	            }
85	
86	            <div class="form-actions">
87	              <button
88	                type="submit"
89	                class="btn btn--primary"
90	                [disabled]="isSubmitting()"
91	                [attr.aria-busy]="isSubmitting() ? 'true' : null"
92	              >
93	                Continuar
94	              </button>
95	            </div>
96	          </form>
97	        }
98	      }
99	    </main>
100	  `,
101	  styles: [`
102	    .form-page {
103	      max-width: 600px;
104	      margin: 0 auto;
105	      padding: var(--space-lg) var(--space-md);
106	    }
107	
108	    .form-title {
109	      font-size: var(--font-size-xl);
110	      margin-bottom: var(--space-lg);
111	    }
112	
113	    .state-loading,
114	    .state-error,
115	    .state-empty {
116	      padding: var(--space-lg);
117	      text-align: center;
118	    }
119	
120	    .loading-spinner {
121	      width: 40px;
122	      height: 40px;
123	      border: 4px solid var(--color-border);
124	      border-top-color: var(--color-primary);
125	      border-radius: 50%;
126	      animation: spin 0.8s linear infinite;
127	      margin: 0 auto var(--space-md);
128	    }
129	
130	    @keyframes spin {
131	      to { transform: rotate(360deg); }
132	    }
133	
134	    .applicant-form {
135	      display: flex;
136	      flex-direction: column;
137	    }
138	
139	    .form-actions {
140	      display: flex;
