160	    }
161	
162	    .btn--primary {
163	      background: var(--color-primary);
164	      color: #fff;
165	
166	      &:hover:not(:disabled) {
167	        background: var(--color-primary-dark);
168	      }
169	    }
170	
171	    .btn--secondary {
172	      background: transparent;
173	      color: var(--color-primary);
174	      border: 2px solid var(--color-primary);
175	
176	      &:hover:not(:disabled) {
177	        background: #eef4fc;
178	      }
179	    }
180	
181	    // Responsive (AC-01.14) — 375px
182	    @media (max-width: 639px) {
183	      .form-page {
184	        padding: var(--space-md) var(--space-sm);
185	      }
186	
187	      .btn {
188	        width: 100%;
189	      }
190	
191	      .form-actions {
192	        justify-content: stretch;
193	      }
194	    }
195	
196	    // 1280px+ — form gets some breathing room
197	    @media (min-width: 1280px) {
198	      .form-page {
199	        padding: var(--space-xl) var(--space-lg);
200	      }
201	    }
202	  `],
203	})
204	export class ApplicantFormComponent implements OnInit, OnDestroy {
205	  readonly msgs = SYSTEM_MESSAGES;
206	
207	  readonly #strapi = inject(StrapiClient);
208	  readonly #countryContext = inject(CountryContext);
209	  readonly #wizardStore = inject(WizardStore);
210	  readonly #router = inject(Router);
211	
212	  readonly fieldRenderers = viewChildren(FieldRendererComponent);
213	
214	  readonly loadState = signal<LoadState>('loading');
215	  readonly fields = signal<FormField[]>([]);
216	  readonly form = signal<FormGroup>(new FormGroup({}));
217	  readonly isSubmitting = signal(false);
218	
219	  readonly stepTitle = computed(() => {
220	    const country = this.#countryContext.country();
221	    return country === 'CO'
222	      ? 'Datos del titular y del vehículo'
223	      : 'Datos del titular y del vehículo';
224	  });
225	
226	  #loadSub?: Subscription;
227	
228	  ngOnInit(): void {
229	    this.#hydrateFromStore();
230	    this.loadFields();
231	  }
232	
233	  ngOnDestroy(): void {
234	    this.#loadSub?.unsubscribe();
235	    // Save to store on unmount if form is valid (AC-01.5)
236	    if (this.loadState() === 'ready' && this.form().valid) {
237	      const values = this.form().getRawValue() as Record<string, unknown>;
238	      const keys = this.fields().map((f) => f.key);
239	      this.#wizardStore.setApplicant(values, keys);
240	    }
241	  }
242	
243	  loadFields(): void {
244	    this.loadState.set('loading');
245	    this.#loadSub?.unsubscribe();
246	
247	    const country = this.#countryContext.country();
248	
249	    this.#loadSub = this.#strapi.getFormFields(country).subscribe({
250	      next: (fields) => {
251	        if (fields.length === 0) {
252	          this.loadState.set('empty');
253	          return;
254	        }
255	
256	        this.fields.set(fields);
257	        this.form.set(this.#buildForm(fields));
258	        this.#hydrateFormFromStore(fields);
259	        this.loadState.set('ready');
260	      },
261	      error: () => {
262	        this.loadState.set('error');
263	      },
264	    });
265	  }
266	
267	  onSubmit(): void {
268	    if (this.isSubmitting()) return;
269	
