192	export class FieldRendererComponent implements OnInit, OnDestroy {
193	  readonly field = input.required<FormField>();
194	  readonly formGroup = input.required<FormGroup>();
195	
196	  readonly inputRef = viewChild<ElementRef<HTMLElement>>('inputRef');
197	
198	  readonly fieldId = computed(() => `field-${this.field().key}`);
199	  readonly errorId = computed(() => `error-${this.field().key}`);
200	  readonly helpId = computed(() => `help-${this.field().key}`);
