202	  readonly descriptionIds = computed(() => {
203	    const ids: string[] = [];
204	    if (this.field().helpText) ids.push(this.helpId());
205	    if (this.isInvalid()) ids.push(this.errorId());
206	    return ids.length > 0 ? ids.join(' ') : null;
207	  });
208	
209	  readonly #elementRef = inject(ElementRef);
210	
211	  readonly isInvalid = signal(false);
212	  readonly errorMessage = signal<string | null>(null);
213	
214	  /**
215	   * Returns the current FormControl for this field.
216	   * Not a computed() because FormGroup.setControl() mutates the group without
217	   * changing the signal reference — a computed would return a stale value.
218	   * Always read via this method instead.
219	   */
220	  get control(): FormControl {
221	    const ctrl = this.formGroup().get(this.field().key);
222	    if (!ctrl) {
223	      throw new Error(`[FieldRenderer] No control found for key: ${this.field().key}`);
224	    }
225	    return ctrl as FormControl;
226	  }
227	
228	  readonly sortedOptions = computed(() => {
229	    const f = this.field();
230	    if (f.type !== 'select') return [];
231	    return [...f.options].sort((a, b) => a.order - b.order);
232	  });
233	
234	  #statusSub?: Subscription;
235	  #hasShownError = false;
236	
237	  ngOnInit(): void {
238	    this.#watchStatus();
239	  }
240	
241	  ngOnDestroy(): void {
242	    this.#statusSub?.unsubscribe();
243	  }
244	
245	  #watchStatus(): void {
246	    const ctrl = this.control;
247	
248	    this.#statusSub = ctrl.statusChanges.subscribe(() => {
249	      this.#updateErrorState();
250	
251	      // RN-01.14: once first error appears, switch to 'change' mode
252	      if (!this.#hasShownError && ctrl.invalid && ctrl.touched) {
253	        this.#hasShownError = true;
254	        this.#promoteToChangeMode();
255	      }
256	    });
257	
258	    // Initial state
259	    this.#updateErrorState();
260	  }
261	
262	  #updateErrorState(): void {
263	    const ctrl = this.control;
264	    const invalid = ctrl.invalid && (ctrl.touched || ctrl.dirty);
265	    this.isInvalid.set(invalid);
266	
267	    if (invalid && ctrl.errors) {
268	      this.errorMessage.set(this.#resolveErrorMessage());
269	    } else {
270	      this.errorMessage.set(null);
271	    }
272	  }
273	
274	  /**
275	   * Resolves the error message in priority order:
276	   * 1. errorMessage from the specific validation rule that failed
277	   * 2. field.errorMessage (generic)
278	   * ADR-004 §Message de error
279	   */
280	  #resolveErrorMessage(): string {
281	    const ctrl = this.control;
282	    const field = this.field();
283	
284	    if (ctrl.errors) {
285	      const failedKey = Object.keys(ctrl.errors)[0];
286	      const matchingValidation = field.validations.find((v) => v.rule === failedKey);
287	      if (matchingValidation?.errorMessage) {
288	        return matchingValidation.errorMessage;
289	      }
290	    }
291	
292	    return field.errorMessage;
293	  }
294	
295	  /**
296	   * Replaces the current control with a 'change' updateOn mode control.
297	   * This is needed because updateOn cannot be changed on an existing control.
298	   * ADR-004 §Estrategia blur → change tras error.
299	   */
300	  #promoteToChangeMode(): void {
301	    const ctrl = this.control;
302	    const group = this.formGroup();
303	    const key = this.field().key;
304	
305	    const newCtrl = new FormControl(ctrl.value, {
306	      validators: ctrl.validator ?? undefined,
307	      updateOn: 'change',
308	    });
309	
310	    // Preserve touched/dirty state
311	    if (ctrl.touched) newCtrl.markAsTouched();
312	    if (ctrl.dirty) newCtrl.markAsDirty();
313	
314	    group.setControl(key, newCtrl);
315	
316	    // Re-subscribe to the new control
317	    this.#statusSub?.unsubscribe();
318	    this.#statusSub = newCtrl.statusChanges.subscribe(() => {
319	      this.#updateErrorState();
320	    });
321	  }
