/**
 * anio_vehiculo validator — year must be within [currentYear - 20, currentYear + 1] (RN-01.3, RN-01.12).
 * AC-01.6
 */
import type { AbstractControl, ValidationErrors } from '@angular/forms';

/**
 * Returns true if `year` is within the allowed range.
 * Range: [currentYear - 20 .. currentYear + 1]
 */
export function isValidVehicleYear(year: number): boolean {
  const current = new Date().getFullYear();
  return year >= current - 20 && year <= current + 1;
}

export function vehicleYearValidator(control: AbstractControl): ValidationErrors | null {
  const value: unknown = control.value;
  if (value === null || value === undefined || value === '') {
    return null;
  }
  const year = typeof value === 'string' ? parseInt(value, 10) : Number(value);
  if (isNaN(year)) {
    return { anio_vehiculo: true };
  }
  return isValidVehicleYear(year) ? null : { anio_vehiculo: true };
}

/**
 * Application routes.
 * /:country branch uses CanMatch guard (ADR-002).
 * WizardStore is provided per-route for lifecycle isolation (ADR-005).
 */
import { type Routes } from '@angular/router';
import { countryGuard } from './country/country.guard';
import { step2Guard } from './wizard/wizard-step.guard';
import { WizardStore } from './wizard/wizard.store';

export const routes: Routes = [
  {
    path: '',
    pathMatch: 'full',
    redirectTo: 'co',
  },
  {
    path: ':country',
    canMatch: [countryGuard],
    providers: [WizardStore],
    children: [
      {
        path: '',
        pathMatch: 'full',
        redirectTo: 'paso-1',
      },
      {
        path: 'paso-1',
        loadComponent: () =>
          import('./features/applicant-form/applicant-form.component').then(
            (m) => m.ApplicantFormComponent,
          ),
      },
      {
        path: 'paso-2',
        canActivate: [step2Guard],
        loadComponent: () =>
          import('./features/plans/plans.component').then(
            (m) => m.PlansComponent,
          ),
      },
    ],
  },
  {
    path: '**',
    redirectTo: 'co',
  },
];

