/**
 * FieldRendererComponent — renders a single form field by type.
 * Uses @switch (field().type) for discriminated narrowing (ADR-006, RN-01.10).
 * Sets aria-invalid and aria-describedby for accessibility (AC-01.13).
 * AC-01.2, AC-01.8, AC-01.13
 */
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  OnDestroy,
  OnInit,
  computed,
  inject,
  input,
  signal,
  viewChild,
} from '@angular/core';
import { ReactiveFormsModule, FormControl, FormGroup } from '@angular/forms';
import type { FormField } from '../../core/schemas/form-field.schema';
import { FieldErrorComponent } from './field-error.component';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-field-renderer',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ReactiveFormsModule, FieldErrorComponent],
  template: `
    <div class="field-wrapper">
      @switch (field().type) {
        @case ('text') {
          <label [for]="fieldId()" class="field-label">
            {{ field().label }}
            @if (field().required) { <span aria-hidden="true" class="required-mark">*</span> }
          </label>
          <input
            #inputRef
            type="text"
            [id]="fieldId()"
            [formControl]="control"
            [attr.autocomplete]="field().autocomplete ?? null"
            [attr.aria-invalid]="isInvalid() ? 'true' : null"
            [attr.aria-describedby]="descriptionIds()"
            class="field-input"
          />
        }
        @case ('number') {
          <label [for]="fieldId()" class="field-label">
            {{ field().label }}
            @if (field().required) { <span aria-hidden="true" class="required-mark">*</span> }
          </label>
          <input
            #inputRef
            type="number"
            [id]="fieldId()"
            [formControl]="control"
            [attr.aria-invalid]="isInvalid() ? 'true' : null"
            [attr.aria-describedby]="descriptionIds()"
            class="field-input"
          />
        }
        @case ('date') {
          <label [for]="fieldId()" class="field-label">
            {{ field().label }}
            @if (field().required) { <span aria-hidden="true" class="required-mark">*</span> }
          </label>
          <input
            #inputRef
            type="date"
            [id]="fieldId()"
            [formControl]="control"
            [attr.aria-invalid]="isInvalid() ? 'true' : null"
            [attr.aria-describedby]="descriptionIds()"
            class="field-input"
          />
        }
        @case ('checkbox') {
          <div class="field-checkbox-wrapper">
            <input
              #inputRef
              type="checkbox"
              [id]="fieldId()"
              [formControl]="control"
              [attr.aria-invalid]="isInvalid() ? 'true' : null"
              [attr.aria-describedby]="descriptionIds()"
              class="field-checkbox"
            />
            <label [for]="fieldId()" class="field-label field-label--inline">
              {{ field().label }}
              @if (field().required) { <span aria-hidden="true" class="required-mark">*</span> }
            </label>
          </div>
        }
        @case ('select') {
          <label [for]="fieldId()" class="field-label">
            {{ field().label }}
            @if (field().required) { <span aria-hidden="true" class="required-mark">*</span> }
          </label>
          <select
            #inputRef
            [id]="fieldId()"
            [formControl]="control"
            [attr.aria-invalid]="isInvalid() ? 'true' : null"
            [attr.aria-describedby]="descriptionIds()"
            class="field-select"
          >
            <option value="">—</option>
            @for (opt of sortedOptions(); track opt.value) {
              <option [value]="opt.value">{{ opt.label }}</option>
            }
          </select>
        }
      }

      @if (field().helpText) {
        <span [id]="helpId()" class="field-help">{{ field().helpText }}</span>
      }

      <app-field-error
        [errorId]="errorId()"
        [message]="errorMessage()"
      />
    </div>
  `,
  styles: [`
    .field-wrapper {
      display: flex;
      flex-direction: column;
      gap: 4px;
      margin-bottom: var(--space-md);
    }

    .field-label {
      font-size: var(--font-size-base);
      font-weight: 500;
      color: var(--color-text);
    }

    .field-label--inline {
      display: inline;
      font-weight: normal;
    }

    .required-mark {
      margin-left: 2px;
      color: var(--color-error);
    }

    .field-input,
    .field-select {
      width: 100%;
      min-height: var(--touch-target-min);
      padding: var(--space-sm) var(--space-md);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-sm);
      font-size: var(--font-size-base);
      color: var(--color-text);
      background: var(--color-bg);
      transition: border-color 0.15s;

      &:focus-visible {
        outline: 3px solid var(--color-border-focus);
        outline-offset: 2px;
      }

      &[aria-invalid='true'] {
        border-color: var(--color-border-error);
        background: var(--color-error-bg);
      }
    }

