1	/**
2	 * PaymentService — simulates a payment in the browser (RN-03.6, ADR-010).
3	 * No real payment gateway is called; no card data is captured (CLAUDE.md §7).
4	 * Delay: PAYMENT_SIMULATION_DELAY_MS (ADR-010 G-03.4).
5	 * Failure mode: ?simulatePaymentFailure=true in query string (ADR-010 D1-A, G-03.2).
6	 * Idempotence: shareReplay(1) prevents duplicate in-flight calls (AC-03.7).
7	 * AC-03.5, AC-03.6, AC-03.7, G-03.11
8	 */
9	import { Injectable, inject, signal } from '@angular/core';
10	import { ActivatedRoute } from '@angular/router';
11	import { Observable, throwError, of, shareReplay, timer } from 'rxjs';
