const TERMS_API_GLOB = '**/api/legal-terms**';

// Fictional document number used in paso-1 — NEVER the full value in assertions
const FICTIONAL_DOCUMENT = '1023456789';
const FICTIONAL_DOCUMENT_MASKED = '******6789';

