1	/**
2	 * TermsBlocksRendererComponent — safely renders Strapi Blocks content.
3	 * Uses Angular template binding only — zero innerHTML, zero DomSanitizer (ADR-009 D3-A).
4	 * Supports: paragraph, heading (level 2/3), list (ordered/unordered), quote.
5	 * Inline marks: bold → <strong>, italic → <em>, link → <a> (safe URLs only).
6	 * Unknown blocks are omitted + logged (ADR-009 D5-A).
7	 * AC-03.3, AC-03.14
8	 */
9	import { ChangeDetectionStrategy, Component, input } from '@angular/core';
10	import type { Block, InlineNode, TextNode } from '../../core/schemas/terms.schema';
11	import { isSafeUrl } from '../../core/url-safety';
12	
13	/**
14	 * Renders a single inline node: text (with optional bold/italic) or a safe link.
15	 * Uses template binding only — no innerHTML (ADR-009 D3-A).
16	 */
17	@Component({
18	  selector: 'app-inline-node',
19	  standalone: true,
20	  changeDetection: ChangeDetectionStrategy.OnPush,
21	  template: `
22	    @if (node().type === 'link' && safeUrl()) {
23	      <a
24	        [attr.href]="linkUrl()"
25	        rel="noopener noreferrer"
26	        target="_blank"
27	        class="terms-link"
28	      >
29	        @for (child of linkChildren(); track $index) {
30	          @if (child.bold && child.italic) {
31	            <strong><em>{{ child.text }}</em></strong>
32	          } @else if (child.bold) {
33	            <strong>{{ child.text }}</strong>
34	          } @else if (child.italic) {
35	            <em>{{ child.text }}</em>
36	          } @else {
37	            {{ child.text }}
38	          }
39	        }
40	      </a>
41	    } @else if (node().type === 'link' && !safeUrl()) {
42	      @for (child of linkChildren(); track $index) {
43	        {{ child.text }}
44	      }
45	    } @else if (node().type === 'text') {
46	      @if (textBold() && textItalic()) {
47	        <strong><em>{{ textContent() }}</em></strong>
48	      } @else if (textBold()) {
49	        <strong>{{ textContent() }}</strong>
50	      } @else if (textItalic()) {
51	        <em>{{ textContent() }}</em>
52	      } @else {
53	        {{ textContent() }}
54	      }
55	    }
56	  `,
57	  styles: [`
58	    :host { display: contents; }
59	    .terms-link {
60	      color: var(--color-primary, #1a56db);
61	      text-decoration: underline;
62	      &:hover { text-decoration: none; }
63	      &:focus-visible {
64	        outline: 2px solid var(--color-primary, #1a56db);
65	        outline-offset: 2px;
66	        border-radius: 2px;
67	      }
68	    }
69	  `],
70	})
71	export class InlineNodeComponent {
72	  readonly node = input.required<InlineNode>();
73	
74	  protected safeUrl(): boolean {
75	    const n = this.node();
76	    return n.type === 'link' && isSafeUrl(n.url);
77	  }
78	
79	  protected linkUrl(): string | null {
80	    const n = this.node();
81	    return n.type === 'link' ? n.url : null;
82	  }
83	
84	  protected linkChildren(): TextNode[] {
85	    const n = this.node();
86	    return n.type === 'link' ? n.children : [];
87	  }
88	
89	  protected textContent(): string {
90	    const n = this.node();
91	    return n.type === 'text' ? n.text : '';
92	  }
93	
94	  protected textBold(): boolean {
95	    const n = this.node();
96	    return n.type === 'text' ? (n.bold ?? false) : false;
97	  }
98	
99	  protected textItalic(): boolean {
100	    const n = this.node();
101	    return n.type === 'text' ? (n.italic ?? false) : false;
102	  }
103	}
104	
105	/**
106	 * Main renderer for a list of Strapi Blocks.
107	 * Input: blocks: Block[] — a typed array of supported block nodes.
108	 */
109	@Component({
110	  selector: 'app-terms-blocks-renderer',
111	  standalone: true,
112	  changeDetection: ChangeDetectionStrategy.OnPush,
113	  imports: [InlineNodeComponent],
114	  template: `
115	    @for (block of blocks(); track $index) {
116	      @switch (block.type) {
117	        @case ('paragraph') {
118	          <p class="terms-paragraph">
119	            @for (child of block.children; track $index) {
120	              <app-inline-node [node]="child" />
121	            }
122	          </p>
123	        }
124	        @case ('heading') {
125	          @if (block.level === 2) {
126	            <h2 class="terms-heading terms-heading--2">
127	              @for (child of block.children; track $index) {
128	                <app-inline-node [node]="child" />
129	              }
130	            </h2>
131	          }
132	          @if (block.level === 3) {
133	            <h3 class="terms-heading terms-heading--3">
134	              @for (child of block.children; track $index) {
135	                <app-inline-node [node]="child" />
136	              }
137	            </h3>
138	          }
139	        }
140	        @case ('list') {
141	          @if (block.format === 'unordered') {
142	            <ul class="terms-list terms-list--unordered">
143	              @for (item of block.children; track $index) {
144	                <li class="terms-list-item">
145	                  @for (child of item.children; track $index) {
146	                    <app-inline-node [node]="child" />
147	                  }
148	                </li>
149	              }
150	            </ul>
151	          }
152	          @if (block.format === 'ordered') {
153	            <ol class="terms-list terms-list--ordered">
154	              @for (item of block.children; track $index) {
155	                <li class="terms-list-item">
156	                  @for (child of item.children; track $index) {
157	                    <app-inline-node [node]="child" />
158	                  }
159	                </li>
160	              }
161	            </ol>
162	          }
163	        }
164	        @case ('quote') {
