            @for (field of fields(); track field.documentId) {
              <app-field-renderer
                [field]="field"
                [formGroup]="form()"
              />
            }

            <div class="form-actions">
              <button
                type="submit"
                class="btn btn--primary"
                [disabled]="isSubmitting()"
                [attr.aria-busy]="isSubmitting() ? 'true' : null"
              >
                Continuar
              </button>
            </div>
          </form>
        }
