export class ApplicantFormComponent implements OnInit, OnDestroy {
  readonly msgs = SYSTEM_MESSAGES;

  readonly #strapi = inject(StrapiClient);
  readonly #countryContext = inject(CountryContext);
  readonly #wizardStore = inject(WizardStore);
  readonly #router = inject(Router);

  readonly fieldRenderers = viewChildren(FieldRendererComponent);

  readonly loadState = signal<LoadState>('loading');
  readonly fields = signal<FormField[]>([]);
  readonly form = signal<FormGroup>(new FormGroup({}));
  readonly isSubmitting = signal(false);
  readonly formInvalid = signal(true);

  readonly ariaStatusMessage = computed(() => {
    switch (this.loadState()) {
      case 'loading': return this.msgs['form.loading'];
      case 'empty': return this.msgs['form.empty'];
      default: return '';
    }
  });

  #loadSub?: Subscription;
  #statusSub?: Subscription;

  ngOnInit(): void {
    this.loadFields();
  }

  ngOnDestroy(): void {
    this.#loadSub?.unsubscribe();
    this.#statusSub?.unsubscribe();
    // Save to store on unmount if form is valid (AC-01.5)
    if (this.loadState() === 'ready' && this.form().valid) {
      const values = this.form().getRawValue() as Record<string, unknown>;
      this.#wizardStore.setApplicant(values, this.fields());
    }
  }

  loadFields(): void {
    this.loadState.set('loading');
    this.#loadSub?.unsubscribe();
    this.#statusSub?.unsubscribe();

    const country = this.#countryContext.country();

    this.#loadSub = this.#strapi.getFormFields(country).subscribe({
      next: (fields) => {
        if (fields.length === 0) {
          this.loadState.set('empty');
          return;
        }

        this.fields.set(fields);
        const builtForm = this.#buildForm(fields);
        this.form.set(builtForm);
        this.#hydrateFormFromStore(fields);

        // Track form validity for the submit button (F-01-1.2)
        this.formInvalid.set(builtForm.invalid);
        this.#statusSub = builtForm.statusChanges.subscribe(() => {
          this.formInvalid.set(this.form().invalid);
        });

        this.loadState.set('ready');
      },
      error: () => {
        this.loadState.set('error');
      },
    });
  }

  onSubmit(): void {
    if (this.isSubmitting()) return;

    const f = this.form();
    f.markAllAsTouched();
    // Force validators to run individually — markAllAsTouched alone does not
    // re-evaluate controls with updateOn:'blur' that haven't been interacted with (F-01-1.4)
    for (const ctrl of Object.values(f.controls)) {
      ctrl.updateValueAndValidity({ emitEvent: true });
    }

    if (f.invalid) {
      this.#focusFirstInvalidField();
      return;
    }

    this.isSubmitting.set(true);

    const values = f.getRawValue() as Record<string, unknown>;
    this.#wizardStore.setApplicant(values, this.fields());

    const country = this.#countryContext.country().toLowerCase();
    this.#router.navigate([`/${country}/paso-2`]).finally(() => {
      this.isSubmitting.set(false);
    });
  }

  #buildForm(fields: FormField[]): FormGroup {
    const controls: Record<string, FormControl> = {};

    for (const field of fields) {
      const validators = buildValidators(field.required, field.validations);
      const defaultValue = field.defaultValue ?? (field.type === 'checkbox' ? false : '');

      controls[field.key] = new FormControl(defaultValue, {
        validators,
        updateOn: 'blur', // RN-01.14: validate on blur initially
      });
    }

    return new FormGroup(controls);
  }

  /**
   * Restores previously entered values from WizardStore (AC-01.5, RN-01.8).
   * Keys that no longer exist in Strapi are silently ignored (AC-01.4).
   * Error messages are not shown until user re-interacts (AC-01.5).
   */
  #hydrateFormFromStore(fields: FormField[]): void {
    const stored = this.#wizardStore.applicant();
    const snapshot = this.#wizardStore.applicantFieldsSnapshot();

    if (stored === null || snapshot === null) return;

    const currentKeys = new Set(fields.map((f) => f.key));
    const form = this.form();

    // snapshot is now FormField[] — use .key to iterate (F-03-1.3)
    for (const snapshotField of snapshot) {
      const key = snapshotField.key;
      if (currentKeys.has(key) && stored[key] !== undefined) {
        const ctrl = form.get(key);
        if (ctrl) {
          ctrl.setValue(stored[key], { emitEvent: false });
          // Do not mark as touched — errors should not show until user re-interacts (AC-01.5)
        }
      }
    }
  }

  /**
   * Focuses the first invalid control in field order (AC-01.3, AC-01.13).
   */
  #focusFirstInvalidField(): void {
    const orderedFields = this.fields();
    const form = this.form();
    const renderers = this.fieldRenderers();

    for (const field of orderedFields) {
      const ctrl = form.get(field.key);
      if (ctrl?.invalid) {
        const renderer = renderers.find((r) => r.field().key === field.key);
        renderer?.focus();
        break;
      }
    }
  }
}

/**
 * Zod schema for Strapi form-field response.
 * Uses discriminatedUnion by `type` for precise inference (ADR-006).
 * Tolerant parsing: unknown fields are discarded + logged (AC-01.12).
 */
import { z } from 'zod';
import { logStructured } from '../logger';

// ---- Validation rules (RN-01.11, RN-01.12, ADR-004) ----

export const validationRuleSchema = z.enum([
  'required',
  'min',
  'max',
  'minLength',
  'maxLength',
  'pattern',
  'rut',
  'cedula_co',
  'placa_co',
  'patente_cl',
  'mayor_edad',
  'anio_vehiculo',
]);

export type ValidationRule = z.infer<typeof validationRuleSchema>;

const paramsByRule: Record<ValidationRule, z.ZodTypeAny> = {
  required: z.object({}).passthrough().optional(),
  min: z.object({ value: z.number() }),
  max: z.object({ value: z.number() }),
  minLength: z.object({ value: z.number().int().nonnegative() }),
  maxLength: z.object({ value: z.number().int().nonnegative() }),
  pattern: z.object({ regex: z.string().min(1) }),
  rut: z.object({}).passthrough().optional(),
  cedula_co: z.object({}).passthrough().optional(),
  placa_co: z.object({}).passthrough().optional(),
  patente_cl: z.object({}).passthrough().optional(),
  mayor_edad: z.object({}).passthrough().optional(),
  anio_vehiculo: z.object({}).passthrough().optional(),
};

export interface ParsedValidation {
  rule: ValidationRule;
  params: unknown;
  errorMessage?: string;
}

function sanitizeValidations(raw: unknown[], fieldDocumentId: string): ParsedValidation[] {
  const out: ParsedValidation[] = [];

  for (const entry of raw) {
    const base = z
      .object({
        rule: z.unknown(),
        params: z.unknown().optional(),
        errorMessage: z.string().optional().nullable(),
      })
      .safeParse(entry);

    if (!base.success) {
      logStructured('strapi.formFields.validationDiscarded', { fieldDocumentId, reason: 'shape' });
      continue;
    }

    const ruleParsed = validationRuleSchema.safeParse(base.data.rule);
    if (!ruleParsed.success) {
      logStructured('strapi.formFields.validationDiscarded', {
        fieldDocumentId,
        rule: base.data.rule,
        reason: 'unknownRule',
      });
      continue;
    }

    const paramsSchema = paramsByRule[ruleParsed.data];
    const paramsParsed = paramsSchema.safeParse(base.data.params ?? {});
    if (!paramsParsed.success) {
      logStructured('strapi.formFields.validationDiscarded', {
        fieldDocumentId,
        rule: ruleParsed.data,
        reason: 'invalidParams',
      });
      continue;
    }

    out.push({
      rule: ruleParsed.data,
      params: paramsParsed.data,
      errorMessage: base.data.errorMessage ?? undefined,
    });
  }

  return out;
}

// ---- Field option (for select type) ----

export const optionSchema = z.object({
  label: z.string().min(1),
  value: z.string().min(1),
  order: z.number().int().default(0),
});

export type FieldOption = z.infer<typeof optionSchema>;

// ---- Base schema shared by all field types ----

const fieldBaseSchema = z.object({
  documentId: z.string().min(1),
  key: z.string().min(1),
  label: z.string().min(1),
  required: z.boolean(),
  /** Section the field belongs to — used by SummaryComponent to split blocks (F-03-1.3, RN-03.1). */
  section: z.enum(['applicant', 'vehicle']).optional().nullable(),
  helpText: z.string().optional().nullable(),
  errorMessage: z.string().min(1),
  order: z.number().int(),
  defaultValue: z.union([z.string(), z.number(), z.boolean()]).optional().nullable(),
  autocomplete: z.string().optional().nullable(),
  // validations parsed element-by-element in parseFormFields
  validations: z.array(z.unknown()).optional().default([]),
});

// ---- Discriminated union by type (RN-01.10, ADR-006) ----

const textFieldSchema = fieldBaseSchema.extend({ type: z.literal('text') });
const numberFieldSchema = fieldBaseSchema.extend({ type: z.literal('number') });
const dateFieldSchema = fieldBaseSchema.extend({ type: z.literal('date') });
const checkboxFieldSchema = fieldBaseSchema.extend({ type: z.literal('checkbox') });
// select requires at least 1 option (AC-01.8)
const selectFieldSchema = fieldBaseSchema.extend({
  type: z.literal('select'),
  options: z.array(optionSchema).min(1),
});

export const formFieldSchema = z.discriminatedUnion('type', [
  textFieldSchema,
  numberFieldSchema,
  dateFieldSchema,
  checkboxFieldSchema,
  selectFieldSchema,
]);

type RawFormField = z.infer<typeof formFieldSchema>;

/**
 * FormField is the domain type used by the renderer and form-builder.
 * validations is re-typed to ParsedValidation[] after sanitization.
 * Uses a mapped type over each variant to preserve the discriminated union
 * so TypeScript can narrow f.options after `if (f.type !== 'select')`.
 */
export type FormField = {
  [K in RawFormField['type']]: Omit<Extract<RawFormField, { type: K }>, 'validations'> & {
    validations: ParsedValidation[];
  };
}[RawFormField['type']];

// ---- Tolerant top-level parser (AC-01.12) ----

const envelopeSchema = z.object({
  data: z.array(z.unknown()),
});

/**
 * parseFormFields — parses Strapi envelope tolerantly.
 * - Invalid envelope → returns [] and logs.
 * - Each item is safeParsed individually; failures → log + skip (AC-01.12).
 * - Result is sorted by `order` ascending (AC-01.1).
 * - Only published items are returned (Strapi query uses publicationState=live — AC-01.15).
 */
export function parseFormFields(raw: unknown): FormField[] {
  const envelopeResult = envelopeSchema.safeParse(raw);
  if (!envelopeResult.success) {
    logStructured('strapi.formFields.envelopeInvalid', {
      issues: envelopeResult.error.issues,
    });
    return [];
  }

  const fields: FormField[] = [];

  for (const item of envelopeResult.data.data) {
    const result = formFieldSchema.safeParse(item);
    if (!result.success) {
      const documentId =
        (item as { documentId?: string } | null)?.documentId ?? 'unknown';
      logStructured('strapi.formFields.fieldDiscarded', {
        documentId,
        issues: result.error.issues.map((i) => ({
          path: i.path,
          code: i.code,
          message: i.message,
        })),
      });
      continue;
    }

    const sanitizedValidations = sanitizeValidations(
      result.data.validations,
      result.data.documentId,
    );

    fields.push({
      ...result.data,
      validations: sanitizedValidations,
    } as FormField);
  }

  return fields.sort((a, b) => a.order - b.order);
}

