    const payBtn = page.getByRole('button', { name: 'Pagar' });
    let payFocused = false;
    for (let i = 0; i < 5 && !payFocused; i++) {
      payFocused = await payBtn.evaluate((el) => document.activeElement === el);
      if (!payFocused) await page.keyboard.press('Tab');
